-- =============================================================================
-- Hand-written section (Prisma cannot express CHECK constraints or seed lookup rows).
-- Prisma ignores CHECK constraints when diffing, so future migrations keep them.
--
-- Money rule mirrored in apps/api/src/domain/money.ts:
--   x% of an amount = ROUND(amount * rate_bps / 10000), half away from zero
--   (= half-up for the non-negative amounts used here). Cast to numeric first so
--   large amounts never overflow 32-bit integers inside the expression.
-- =============================================================================

-- ---------- users ----------
ALTER TABLE "users"
  ADD CONSTRAINT "users_email_or_phone_chk" CHECK ("email" IS NOT NULL OR "phone" IS NOT NULL);

-- ---------- locations ----------
ALTER TABLE "locations"
  ADD CONSTRAINT "locations_latitude_chk"  CHECK ("latitude"  IS NULL OR "latitude"  BETWEEN -90 AND 90),
  ADD CONSTRAINT "locations_longitude_chk" CHECK ("longitude" IS NULL OR "longitude" BETWEEN -180 AND 180),
  ADD CONSTRAINT "locations_not_own_parent_chk" CHECK ("parent_id" IS NULL OR "parent_id" <> "id");

-- ---------- providers ----------
ALTER TABLE "providers"
  ADD CONSTRAINT "providers_commission_rate_chk"
    CHECK ("commission_rate_bps" IS NULL OR "commission_rate_bps" BETWEEN 0 AND 10000);

ALTER TABLE "provider_documents"
  ADD CONSTRAINT "provider_documents_size_chk" CHECK ("size_bytes" > 0);

-- ---------- listings ----------
ALTER TABLE "listings"
  ADD CONSTRAINT "listings_currency_chk" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "listings_base_price_chk" CHECK ("base_price_minor" >= 0),
  ADD CONSTRAINT "listings_service_charge_rate_chk" CHECK ("service_charge_rate_bps" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "listings_tax_rate_chk" CHECK ("tax_rate_bps" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "listings_commission_rate_chk"
    CHECK ("commission_rate_bps" IS NULL OR "commission_rate_bps" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "listings_attributes_object_chk" CHECK (jsonb_typeof("attributes") = 'object'),
  ADD CONSTRAINT "listings_not_own_parent_chk" CHECK ("parent_id" IS NULL OR "parent_id" <> "id");

ALTER TABLE "hotel_details"
  ADD CONSTRAINT "hotel_details_star_rating_chk" CHECK ("star_rating" IS NULL OR "star_rating" BETWEEN 1 AND 5),
  ADD CONSTRAINT "hotel_details_check_in_time_chk"  CHECK ("check_in_time"  ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  ADD CONSTRAINT "hotel_details_check_out_time_chk" CHECK ("check_out_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$');

ALTER TABLE "hotel_room_details"
  ADD CONSTRAINT "hotel_room_details_max_adults_chk" CHECK ("max_adults" >= 1),
  ADD CONSTRAINT "hotel_room_details_max_children_chk" CHECK ("max_children" >= 0),
  ADD CONSTRAINT "hotel_room_details_bed_count_chk" CHECK ("bed_count" >= 1),
  ADD CONSTRAINT "hotel_room_details_size_chk" CHECK ("size_sqm" IS NULL OR "size_sqm" > 0);

ALTER TABLE "bus_route_details"
  ADD CONSTRAINT "bus_route_details_departure_time_chk" CHECK ("departure_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  ADD CONSTRAINT "bus_route_details_duration_chk" CHECK ("duration_minutes" > 0),
  ADD CONSTRAINT "bus_route_details_seat_capacity_chk" CHECK ("seat_capacity" > 0),
  ADD CONSTRAINT "bus_route_details_distinct_endpoints_chk" CHECK ("origin_location_id" <> "destination_location_id");

ALTER TABLE "guide_service_details"
  ADD CONSTRAINT "guide_service_details_group_size_chk" CHECK ("max_group_size" >= 1);

ALTER TABLE "tour_details"
  ADD CONSTRAINT "tour_details_duration_chk" CHECK ("duration_days" >= 1),
  ADD CONSTRAINT "tour_details_group_size_chk" CHECK ("max_group_size" >= 1),
  ADD CONSTRAINT "tour_details_altitude_chk" CHECK ("max_altitude_meters" IS NULL OR "max_altitude_meters" > 0);

ALTER TABLE "flight_route_details"
  ADD CONSTRAINT "flight_route_details_departure_time_chk" CHECK ("departure_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  ADD CONSTRAINT "flight_route_details_duration_chk" CHECK ("duration_minutes" > 0),
  ADD CONSTRAINT "flight_route_details_distinct_airports_chk" CHECK ("origin_airport_code" <> "destination_airport_code");

-- ---------- inventory: the database itself refuses overbooking ----------
ALTER TABLE "inventory_slots"
  ADD CONSTRAINT "inventory_slots_capacity_total_chk" CHECK ("capacity_total" >= 0),
  ADD CONSTRAINT "inventory_slots_capacity_booked_chk" CHECK ("capacity_booked" >= 0),
  ADD CONSTRAINT "inventory_slots_no_overbooking_chk" CHECK ("capacity_booked" <= "capacity_total"),
  ADD CONSTRAINT "inventory_slots_price_override_chk" CHECK ("price_override_minor" IS NULL OR "price_override_minor" >= 0);

-- ---------- cancellation policies ----------
ALTER TABLE "cancellation_policies"
  ADD CONSTRAINT "cancellation_policies_rules_array_chk" CHECK (jsonb_typeof("rules") = 'array');

-- ---------- trips (stored aggregates of their items) ----------
ALTER TABLE "trips"
  ADD CONSTRAINT "trips_currency_chk" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "trips_amounts_non_negative_chk" CHECK (
    "subtotal_minor" >= 0 AND "service_charge_minor" >= 0 AND "tax_minor" >= 0
    AND "total_minor" >= 0 AND "commission_total_minor" >= 0),
  ADD CONSTRAINT "trips_total_chk"
    CHECK ("total_minor" = "subtotal_minor" + "service_charge_minor" + "tax_minor"),
  ADD CONSTRAINT "trips_commission_within_subtotal_chk" CHECK ("commission_total_minor" <= "subtotal_minor");

-- ---------- booking items: every money field must agree with the formula ----------
ALTER TABLE "booking_items"
  ADD CONSTRAINT "booking_items_currency_chk" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "booking_items_quantity_chk" CHECK ("quantity" > 0),
  ADD CONSTRAINT "booking_items_traveller_count_chk" CHECK ("traveller_count" > 0),
  ADD CONSTRAINT "booking_items_dates_chk" CHECK ("end_date" IS NULL OR "end_date" > "start_date"),
  ADD CONSTRAINT "booking_items_rates_chk" CHECK (
    "service_charge_rate_bps" BETWEEN 0 AND 10000
    AND "tax_rate_bps" BETWEEN 0 AND 10000
    AND "commission_rate_bps" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "booking_items_subtotal_chk" CHECK ("subtotal_minor" >= 0),
  ADD CONSTRAINT "booking_items_service_charge_chk"
    CHECK ("service_charge_minor" = ROUND("subtotal_minor"::numeric * "service_charge_rate_bps" / 10000)),
  ADD CONSTRAINT "booking_items_tax_chk"
    CHECK ("tax_minor" = ROUND(("subtotal_minor"::numeric + "service_charge_minor") * "tax_rate_bps" / 10000)),
  ADD CONSTRAINT "booking_items_total_chk"
    CHECK ("total_minor" = "subtotal_minor" + "service_charge_minor" + "tax_minor"),
  ADD CONSTRAINT "booking_items_commission_chk"
    CHECK ("commission_minor" = ROUND("subtotal_minor"::numeric * "commission_rate_bps" / 10000)),
  ADD CONSTRAINT "booking_items_payout_chk"
    CHECK ("provider_payout_minor" = "total_minor" - "commission_minor"),
  ADD CONSTRAINT "booking_items_refund_chk"
    CHECK ("refunded_minor" >= 0 AND "refunded_minor" <= "total_minor"),
  ADD CONSTRAINT "booking_items_attributes_object_chk" CHECK (jsonb_typeof("attributes") = 'object');

ALTER TABLE "booking_item_slots"
  ADD CONSTRAINT "booking_item_slots_units_chk" CHECK ("units" > 0),
  ADD CONSTRAINT "booking_item_slots_unit_price_chk" CHECK ("unit_price_minor" >= 0),
  ADD CONSTRAINT "booking_item_slots_amount_chk"
    CHECK ("amount_minor"::numeric = "units"::numeric * "unit_price_minor");

-- ---------- payments, payouts, invoices ----------
ALTER TABLE "payments"
  ADD CONSTRAINT "payments_currency_chk" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "payments_amount_chk" CHECK ("amount_minor" > 0);

ALTER TABLE "payment_allocations"
  ADD CONSTRAINT "payment_allocations_amount_chk" CHECK ("amount_minor" > 0);

ALTER TABLE "payouts"
  ADD CONSTRAINT "payouts_currency_chk" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "payouts_amount_chk" CHECK ("amount_minor" >= 0),
  ADD CONSTRAINT "payouts_period_chk" CHECK ("period_end" >= "period_start");

ALTER TABLE "provider_invoices"
  ADD CONSTRAINT "provider_invoices_currency_chk" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "provider_invoices_amount_chk" CHECK ("amount_minor" >= 0);

-- ---------- reviews ----------
ALTER TABLE "reviews"
  ADD CONSTRAINT "reviews_rating_chk" CHECK ("rating" BETWEEN 1 AND 5);

